-- 1. Row-Grain Portfolio Enriched Semantic View (for QuickSight SPICE & Power BI DirectQuery)
CREATE OR REPLACE VIEW gold.v_semantic_evm_portfolio AS
SELECT
    f.snapshot_date,
    d.fiscal_year,
    d.fiscal_quarter,
    d.month_name,
    f.project_sk,
    p.project_id,
    p.project_name,
    f.region_code,
    r.region_name,
    r.maturity_stage,
    p.practice_area,
    p.contract_type,
    p.project_manager,
    f.bac_usd,
    f.cum_pv_usd,
    f.cum_ev_usd,
    f.cum_ac_labor_usd,
    f.cum_ac_cloud_usd,
    f.cum_ac_total_usd,
    f.pct_complete
FROM gold.fact_evm_daily f
INNER JOIN gold.dim_project p ON f.project_sk = p.project_sk
INNER JOIN gold.dim_region r  ON f.region_code = r.region_code
INNER JOIN gold.dim_date d    ON f.snapshot_date = d.snapshot_date;

-- 2. Executive Pre-Weighted Semantic Rollup View (Prevents Naive AVG(CPI) Across Projects!)
CREATE OR REPLACE VIEW gold.v_semantic_evm_executive_kpis AS
SELECT
    f.snapshot_date,
    f.region_code,
    p.practice_area,
    SUM(f.bac_usd) AS budget_at_completion_usd,
    SUM(f.cum_pv_usd) AS planned_value_usd,
    SUM(f.cum_ev_usd) AS earned_value_usd,
    SUM(f.cum_ac_labor_usd) AS actual_labor_cost_usd,
    SUM(f.cum_ac_cloud_usd) AS actual_cloud_cost_usd,
    SUM(f.cum_ac_total_usd) AS actual_cost_total_usd,
    SUM(f.cum_ev_usd) - SUM(f.cum_ac_total_usd) AS cost_variance_usd,
    SUM(f.cum_ev_usd) - SUM(f.cum_pv_usd) AS schedule_variance_usd,
    ROUND(SUM(f.cum_ev_usd) / NULLIF(SUM(f.cum_ac_total_usd), 0), 4) AS cost_performance_index,
    ROUND(SUM(f.cum_ev_usd) / NULLIF(SUM(f.cum_pv_usd), 0), 4) AS schedule_performance_index,
    ROUND(SUM(f.bac_usd) / NULLIF(SUM(f.cum_ev_usd) / NULLIF(SUM(f.cum_ac_total_usd), 0), 0), 2) AS estimate_at_completion_usd,
    ROUND(SUM(f.cum_ac_total_usd) + ((SUM(f.bac_usd) - SUM(f.cum_ev_usd)) / NULLIF((SUM(f.cum_ev_usd) / NULLIF(SUM(f.cum_ac_total_usd), 0)) * (SUM(f.cum_ev_usd) / NULLIF(SUM(f.cum_pv_usd), 0)), 0)), 2) AS eac_composite_usd,
    ROUND(SUM(f.bac_usd) - (SUM(f.bac_usd) / NULLIF(SUM(f.cum_ev_usd) / NULLIF(SUM(f.cum_ac_total_usd), 0), 0)), 2) AS variance_at_completion_usd,
    ROUND((SUM(f.bac_usd) - SUM(f.cum_ev_usd)) / NULLIF(SUM(f.bac_usd) - SUM(f.cum_ac_total_usd), 0), 4) AS to_complete_performance_index
FROM gold.fact_evm_daily f
INNER JOIN gold.dim_project p ON f.project_sk = p.project_sk
GROUP BY f.snapshot_date, f.region_code, p.practice_area;

